    static Long number(JSONObject o,String key,long min,long max){Object v=o.opt(key);if(!(v instanceof Integer)&&!(v instanceof Long))return null;long n=((Number)v).longValue();return n>=min&&n<=max?n:null;}
    static Double validNumber(JSONObject o,String key,double min,double max){Object v=o.opt(key);if(!(v instanceof Number))return null;double n=((Number)v).doubleValue();return Double.isFinite(n)&&n>=min&&n<=max?n:null;}
    private static void paired(Builder b){if(b.selection.days==1)return;int minimum=b.selection.days==7?5:10;for(String[] pair:new String[][]{{"sleep","heart"},{"sleep","activity"},{"nutrition","activity"},{"sleep","strength"}}){Map<Integer,Double> left=b.daily.get(pair[0]),right=b.daily.get(pair[1]);if(left==null||right==null)continue;List<Double>a=new ArrayList<>(),c=new ArrayList<>();for(int index=-b.selection.days+1;index<=0;index++)if(!(index==0&&b.selection.end.equals(LocalDate.now(b.selection.zone)))&&left.containsKey(index)&&right.containsKey(index)){a.add(left.get(index));c.add(right.get(index));}if(a.size()<minimum)continue;String id="paired."+pair[0]+"_"+pair[1];JSONObject metric=NutritionModels.object("id",id,"domains",new JSONArray(Arrays.asList(pair)),"nPairedDays",a.size(),"firstMean",AnalysisHealthSummary.round(AnalysisHealthSummary.mean(a),1),"secondMean",AnalysisHealthSummary.round(AnalysisHealthSummary.mean(c),1),"basis","same_wake_day_independent_observations_no_causality","qualityCeiling","LIMITED");b.pairs.put(metric);NutritionModels.put(b.evidence,id,metric);}}
    private static void nutritionPeriod(Builder b,JSONObject domain,Map<Integer,JSONObject> values){int entries=0,items=0,known=0,photo=0,manual=0,observed=0,goalDays=0;long kcal=0,p=0,f=0,c=0;boolean pk=true,fk=true,ck=true;List<Double> goals=new ArrayList<>(),differences=new ArrayList<>();for(Map.Entry<Integer,JSONObject> row:values.entrySet()){if(!b.selection.current(row.getKey()))continue;JSONObject v=row.getValue();entries+=v.optInt("confirmedEntryCount");items+=v.optInt("confirmedItemCount");known+=v.optInt("macrosKnownItems");photo+=v.optInt("photoEstimatedItems");manual+=v.optInt("manualEstimatedItems");if(!v.isNull("kcalMilli")){observed++;kcal+=v.optLong("kcalMilli");pk&=!v.isNull("proteinMg");fk&=!v.isNull("fatMg");ck&=!v.isNull("carbohydrateMg");if(!v.isNull("proteinMg"))p+=v.optLong("proteinMg");if(!v.isNull("fatMg"))f+=v.optLong("fatMg");if(!v.isNull("carbohydrateMg"))c+=v.optLong("carbohydrateMg");}if(!v.isNull("goalKcalMilli")){goalDays++;goals.add((double)v.optLong("goalKcalMilli"));if(v.optBoolean("completeDayDeclared")&&!v.isNull("differenceToUserGoalKcalMilli"))differences.add((double)v.optLong("differenceToUserGoalKcalMilli"));}}for(Object[] metric:new Object[][]{{"confirmedEntryCount",entries,"count"},{"confirmedItemCount",items,"count"},{"macrosKnownItems",known,"count"},{"photoEstimatedItems",photo,"count"},{"manualEstimatedItems",manual,"count"},{"registeredKcalMilli",observed==0?null:kcal,"kcalMilli"},{"registeredProteinMg",observed==0||!pk?null:p,"mg"},{"registeredFatMg",observed==0||!fk?null:f,"mg"},{"registeredCarbohydrateMg",observed==0||!ck?null:c,"mg"},{"userGoalDays",goalDays,"days"},{"meanUserGoalKcalMilli",AnalysisHealthSummary.round(AnalysisHealthSummary.mean(goals),0),"kcalMilli"},{"meanDifferenceToUserGoalKcalMilliCompleteDays",AnalysisHealthSummary.round(AnalysisHealthSummary.mean(differences),0),"kcalMilli"}})b.metric(domain,"period."+metric[0],metric[1],(String)metric[2],"confirmed_registered_values_in_selected_days",items);}
    private static void activityPeriod(Builder b,JSONObject domain){int sessions=0,stepKnown=0,distanceKnown=0;long steps=0,coverage=0;double distance=0;boolean coverageKnown=true;for(JSONObject w:b.source.workouts){if(!"SAVED".equals(w.optString("status"))||!ExpansionModels.PHONE.equals(w.optString("source"))||!b.selection.current(b.selection.index(workoutDate(w,b.selection.zone))))continue;sessions++;Long observed=number(w,"stepsObserved",0,Integer.MAX_VALUE),span=number(w,"stepsCoverageMillis",0,Long.MAX_VALUE);if(observed!=null){stepKnown++;steps+=observed;}if(span==null)coverageKnown=false;else coverage+=span;Double meters=validNumber(w,"distanceMeters",0,1e8);if(meters!=null){distanceKnown++;distance+=meters;}}
        b.metric(domain,"period.phoneStepsObserved",stepKnown==0?null:steps,"steps","sum_registered_step_observations_in_phone_active_segments_not_full_activity",stepKnown,"PARTIAL_HISTORY");b.metric(domain,"period.phoneStepObservedSessionCount",stepKnown,"count","phone_sessions_with_known_step_observations",sessions);b.metric(domain,"period.phoneStepsCoverageMillis",sessions==0||!coverageKnown?null:coverage,"ms","sum_known_step_observation_intervals",sessions,"PARTIAL_HISTORY");b.metric(domain,"period.phoneRegisteredDistanceMeters",distanceKnown==0?null:AnalysisHealthSummary.round(distance,1),"m","sum_valid_registered_gps_partial_routes_phone_source_only",distanceKnown,"PARTIAL_HISTORY");b.metric(domain,"period.phoneDistanceObservedSessionCount",distanceKnown,"count","phone_sessions_with_valid_partial_route_distance",sessions);}
